class Solution { public int[] asteroidCollision(int[] asteroids){List<Integer> stack=new ArrayList<>();for(int asteroid:asteroids){boolean alive=true;while(alive&&asteroid<0&&!stack.isEmpty()&&stack.get(stack.size()-1)>0){int top=stack.get(stack.size()-1);if(top<-asteroid)stack.remove(stack.size()-1);else{if(top==-asteroid)stack.remove(stack.size()-1);alive=false;}}if(alive)stack.add(asteroid);}return stack.stream().mapToInt(Integer::intValue).toArray();} }
